"use client";

import { AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID } from "@lib/automation-setup-connected-integrations";
import { formatPiiTypeLabel, maskPiiForClientPreview } from "@lib/pii/client";
import { TOKEN_PATTERN } from "@lib/pii/token";
import {
  type AskUserAnswer,
  type AskUserQuestionType,
  type AskUserRequest,
  type AskUserResult,
  countAnsweredQuestions,
  formatAskUserAnswerLine,
  formatAskUserResultSummary,
  type NormalizedAskUserQuestion,
} from "@lib/session-ask-user";
import { isAskUserQuestionVisible } from "@lib/session-ask-user-conditional";
import { partitionAskUserQuestions } from "@lib/session-ask-user-single-choice";
import { Link } from "@tanstack/react-router";
import { DisclosureChevron } from "@web/components/disclosure";
import { SessionMessageContent } from "@web/components/session-chat/session-message-content";
import { TurnChromeCard } from "@web/components/session-chat/turn-chrome-card";
import { SESSION_EASE_OUT } from "@web/lib/session-motion";
import { workBlockIconClass } from "@web/lib/session-work-block-chrome";
import { cn } from "@web/lib/utils";
import type { TFunction } from "i18next";
import { ChevronDownIcon, MessageCircleQuestion } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useId, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Field, FieldDescription, FieldError, FieldGroup, FieldTitle } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

/** Announce draft answers without reading raw PII into screen readers (TAC-546). */
function announceAskUserDraftSummary(summary: string): string {
  const preview = maskPiiForClientPreview(summary);
  if (preview.piiSpans.length === 0) return summary;
  return preview.content.replace(TOKEN_PATTERN, (_token, type: string) => {
    return `protected ${formatPiiTypeLabel(type)}`;
  });
}

const OTHER_VALUE = "__other__";

const ASK_USER_PICKER_TRIGGER_CLASS =
  "flex h-9 w-full items-center justify-between gap-1.5 rounded-sm border border-input bg-muted px-3 py-2 text-sm transition-colors outline-none hover:bg-accent focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-red-600 dark:aria-invalid:ring-red-600/40";

const ASK_USER_PICKER_MENU_CLASS =
  "max-h-60 overflow-x-hidden overflow-y-auto overscroll-contain p-1";

type DraftAnswers = Record<
  string,
  {
    type: AskUserQuestionType;
    value: string | string[];
    otherText: string;
    useOther: boolean;
  }
>;

function buildInitialDraft(questions: readonly NormalizedAskUserQuestion[]): DraftAnswers {
  const draft: DraftAnswers = {};
  for (const question of questions) {
    if (question.type === "checkbox") {
      const defaults = Array.isArray(question.default) ? [...question.default] : [];
      draft[question.id] = {
        type: question.type,
        value: defaults,
        otherText: "",
        useOther: false,
      };
      continue;
    }
    if (question.type === "radio") {
      const defaultValue = typeof question.default === "string" ? question.default.trim() : "";
      const matchesOption = question.options.some((option) => option.value === defaultValue);
      if (defaultValue && !matchesOption && question.allowOther) {
        draft[question.id] = {
          type: question.type,
          value: "",
          otherText: defaultValue,
          useOther: true,
        };
      } else {
        draft[question.id] = {
          type: question.type,
          value: matchesOption ? defaultValue : "",
          otherText: "",
          useOther: false,
        };
      }
      continue;
    }
    const defaultValue = typeof question.default === "string" ? question.default : "";
    draft[question.id] = {
      type: question.type,
      value: defaultValue,
      otherText: "",
      useOther: false,
    };
  }
  return draft;
}

function validateDraft(
  questions: readonly NormalizedAskUserQuestion[],
  draft: DraftAnswers,
  t: TFunction<"sessions">,
): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const question of questions) {
    const entry = draft[question.id];
    if (!entry) continue;
    if (!question.required) continue;

    if (question.type === "radio") {
      if (entry.useOther) {
        if (!entry.otherText.trim()) errors[question.id] = t("askUser.validation.custom");
        continue;
      }
      if (!entry.value) errors[question.id] = t("askUser.validation.one");
      continue;
    }

    if (question.type === "checkbox") {
      const selected = Array.isArray(entry.value) ? entry.value : [];
      if (selected.length === 0 && !(entry.useOther && entry.otherText.trim())) {
        errors[question.id] = t("askUser.validation.atLeastOne");
      }
      continue;
    }

    if (question.type === "text" && !String(entry.value).trim()) {
      errors[question.id] = t("askUser.validation.response");
    }
  }
  return errors;
}

function draftToAnswers(
  questions: readonly NormalizedAskUserQuestion[],
  draft: DraftAnswers,
): AskUserAnswer[] {
  return questions.map((question) => {
    const entry = draft[question.id];
    if (!entry) {
      return { id: question.id, type: question.type, value: "", wasCustom: false };
    }

    if (question.type === "radio") {
      if (entry.useOther) {
        return {
          id: question.id,
          type: "radio",
          value: entry.otherText.trim(),
          wasCustom: true,
        };
      }
      return {
        id: question.id,
        type: "radio",
        value: String(entry.value),
        wasCustom: false,
      };
    }

    if (question.type === "checkbox") {
      const selected = Array.isArray(entry.value) ? [...entry.value] : [];
      if (entry.useOther && entry.otherText.trim()) {
        selected.push(entry.otherText.trim());
      }
      return {
        id: question.id,
        type: "checkbox",
        value: selected,
        wasCustom: entry.useOther && entry.otherText.trim().length > 0,
      };
    }

    return {
      id: question.id,
      type: "text",
      value: String(entry.value),
      wasCustom: false,
    };
  });
}

