const autoSubmittedAskUserRequestIds = new Set<string>();

export function SessionAskUserForm({
  request,
  resolution,
  onSubmit,
  onCancel,
  className,
  sessionId,
  defaultExpanded = false,
}: {
  request: AskUserRequest;
  resolution?: AskUserResult;
  onSubmit?: (result: AskUserResult) => void;
  onCancel?: () => void;
  className?: string;
  sessionId?: string;
  /** When rendering a resolved receipt, start expanded (dev gallery / tests). */
  defaultExpanded?: boolean;
}) {
  const { t } = useTranslation(["sessions", "common"]);
  const { visibleQuestions: baseVisibleQuestions, implicitAnswers } = useMemo(
    () => partitionAskUserQuestions(request.questions),
    [request.questions],
  );
  const [draft, setDraft] = useState<DraftAnswers>(() => buildInitialDraft(request.questions));
  const [errors, setErrors] = useState<Record<string, string>>({});
  const autoSubmittedRef = useRef(false);
  const visibleQuestions = useMemo(() => {
    const answerSnapshot = Object.fromEntries(
      Object.entries(draft).map(([id, entry]) => [id, { value: entry.value }]),
    );
    return baseVisibleQuestions.filter((question) =>
      isAskUserQuestionVisible(question, answerSnapshot),
    );
  }, [baseVisibleQuestions, draft]);

  const draftResetKey = useMemo(
    () => `${request.requestId}:${JSON.stringify(request.questions)}`,
    [request.requestId, request.questions],
  );

  // biome-ignore lint/correctness/useExhaustiveDependencies: intentional stable hook dependencies
  useEffect(() => {
    autoSubmittedRef.current = false;
    setDraft(buildInitialDraft(request.questions));
    setErrors({});
  }, [draftResetKey]);

  useEffect(() => {
    if (resolution || !onSubmit || autoSubmittedRef.current) return;
    if (visibleQuestions.length > 0) return;
    if (implicitAnswers.length === 0) return;
    if (autoSubmittedAskUserRequestIds.has(request.requestId)) return;
    autoSubmittedRef.current = true;
    autoSubmittedAskUserRequestIds.add(request.requestId);
    onSubmit({
      requestId: request.requestId,
      cancelled: false,
      answers: implicitAnswers,
    });
  }, [implicitAnswers, onSubmit, request.requestId, resolution, visibleQuestions.length]);

  const previewSummary = useMemo(() => {
    const answers = [...implicitAnswers, ...draftToAnswers(visibleQuestions, draft)];
    const summary = formatAskUserResultSummary(request, {
      requestId: request.requestId,
      cancelled: false,
      answers,
    });
    return announceAskUserDraftSummary(summary);
  }, [draft, implicitAnswers, request, visibleQuestions]);

  if (resolution) {
    return (
      <SessionAskUserReceipt
        request={request}
        result={resolution}
        className={className}
        sessionId={sessionId}
        defaultExpanded={defaultExpanded}
      />
    );
  }

  if (visibleQuestions.length === 0) {
    return null;
  }

  const updateQuestion = (questionId: string, next: DraftAnswers[string]) => {
    setDraft((previous) => ({ ...previous, [questionId]: next }));
    setErrors((previous) => {
      if (!previous[questionId]) return previous;
      const copy = { ...previous };
      delete copy[questionId];
      return copy;
    });
  };

  const handleSubmit = () => {
    const nextErrors = validateDraft(visibleQuestions, draft, t);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;
    onSubmit?.({
      requestId: request.requestId,
      cancelled: false,
      answers: [...implicitAnswers, ...draftToAnswers(visibleQuestions, draft)],
    });
  };

  const handleCancel = () => {
    onCancel?.();
  };

  return (
    <TurnChromeCard
      as="form"
      state="gold"
      className={className}
      icon={
        <MessageCircleQuestion
          className={cn("size-4 shrink-0", workBlockIconClass("gold"))}
          aria-hidden="true"
        />
      }
      title={request.title?.trim() || t("askUser.title")}
      description={request.description ?? undefined}
      onSubmit={(event) => {
        event.preventDefault();
        handleSubmit();
      }}
    >
      <div className="flex flex-col gap-4 px-3 pt-3 pb-3">
        <FieldGroup>
          {visibleQuestions.map((question) => {
            const entry = draft[question.id];
            if (!entry) return null;
            const error = errors[question.id];

            if (question.type === "radio") {
              return (
                <RadioQuestionField
                  key={question.id}
                  question={question}
                  draft={entry}
                  error={error}
                  onChange={(next) => updateQuestion(question.id, next)}
                />
              );
            }

            if (question.type === "checkbox") {
              if (question.id === AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID) {
                return (
                  <ConnectedIntegrationsQuestionField
                    key={question.id}
                    question={question}
                    draft={entry}
                    error={error}
                    onChange={(next) => updateQuestion(question.id, next)}
                  />
                );
              }
              return (
                <CheckboxQuestionField
                  key={question.id}
                  question={question}
                  draft={entry}
                  error={error}
                  onChange={(next) => updateQuestion(question.id, next)}
                />
              );
            }

            return (
              <TextQuestionField
                key={question.id}
                question={question}
                draft={entry}
                error={error}
                onChange={(next) => updateQuestion(question.id, next)}
              />
            );
          })}
        </FieldGroup>

        <div className="flex flex-wrap items-center gap-2">
          <Button type="submit" size="sm">
            {t("askUser.submit")}
          </Button>
          <Button type="button" size="sm" variant="ghost" onClick={handleCancel}>
            {t("actions.cancel", { ns: "common" })}
          </Button>
        </div>
      </div>

      <p className="sr-only" aria-live="polite">
        {previewSummary}
      </p>
    </TurnChromeCard>
  );
}

