type BuilderHandoffStartMode = "sync" | "async";

type DraftAnswerState = Record<
  string,
  {
    selected: string[];
    text: string;
    customText: string;
    useCustom: boolean;
  }
>;

const OTHER_VALUE = "__other__";

function buildInitialDraft(questions: readonly BuilderHandoffQuestion[]): DraftAnswerState {
  return Object.fromEntries(
    questions.map((question) => [
      question.id,
      {
        selected: [],
        text: "",
        customText: "",
        useCustom: false,
      },
    ]),
  );
}

function updateDraftEntry(
  current: DraftAnswerState,
  questionId: string,
  patch: Partial<DraftAnswerState[string]>,
): DraftAnswerState {
  const existing = current[questionId] ?? {
    selected: [],
    text: "",
    customText: "",
    useCustom: false,
  };
  return {
    ...current,
    [questionId]: {
      selected: existing.selected,
      text: existing.text,
      customText: existing.customText,
      useCustom: existing.useCustom,
      ...patch,
    },
  };
}

function validateAnswers(
  questions: readonly BuilderHandoffQuestion[],
  draft: DraftAnswerState,
  t: TFunction<"sessions">,
): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const question of questions) {
    if (!question.required) continue;
    const entry = draft[question.id];
    if (!entry) continue;
    if (question.type === "text") {
      if (!entry.text.trim()) errors[question.id] = t("askUser.validation.response");
      continue;
    }
    if (question.type === "radio") {
      if (entry.useCustom) {
        if (!entry.customText.trim()) errors[question.id] = t("builderHandoff.customResponse");
      } else if (!entry.selected[0]) {
        errors[question.id] = t("askUser.validation.one");
      }
      continue;
    }
    if (entry.selected.length === 0 && !(entry.useCustom && entry.customText.trim())) {
      errors[question.id] = t("askUser.validation.atLeastOne");
    }
  }
  return errors;
}

function toAnswers(
  questions: readonly BuilderHandoffQuestion[],
  draft: DraftAnswerState,
): BuilderHandoffAnswer[] {
  const answers: BuilderHandoffAnswer[] = [];
  for (const question of questions) {
    const entry = draft[question.id];
    let answer: BuilderHandoffAnswer;
    if (!entry) {
      answer = {
        id: question.id,
        type: question.type,
        value: question.type === "checkbox" ? [] : "",
        wasCustom: false,
      };
    } else if (question.type === "text") {
      answer = {
        id: question.id,
        type: "text",
        value: entry.text.trim(),
        wasCustom: false,
      };
    } else if (question.type === "radio") {
      answer = {
        id: question.id,
        type: "radio",
        value: entry.useCustom ? entry.customText.trim() : (entry.selected[0] ?? ""),
        wasCustom: entry.useCustom,
      };
    } else {
      const values = [...entry.selected];
      if (entry.useCustom && entry.customText.trim()) values.push(entry.customText.trim());
      answer = {
        id: question.id,
        type: "checkbox",
        value: values,
        wasCustom: entry.useCustom && entry.customText.trim().length > 0,
      };
    }
    const empty = Array.isArray(answer.value)
      ? answer.value.length === 0
      : answer.value.trim().length === 0;
    // Required empties are blocked by validateAnswers; optional blanks are omitted.
    if (empty) continue;
    answers.push(answer);
  }
  return answers;
}

