type TestEnvironment = ReturnType<typeof installReactDomTestEnvironment>;

let testEnvironment: TestEnvironment | null = null;
let htmlFormElementDescriptor: PropertyDescriptor | undefined;

function findElements(
  root: ReactDomTestElement,
  predicate: (element: ReactDomTestElement) => boolean,
): ReactDomTestElement[] {
  const matches = predicate(root) ? [root] : [];
  for (const child of root.children) matches.push(...findElements(child, predicate));
  return matches;
}

function reactHandler(element: ReactDomTestElement, name: "onClick" | "onSubmit") {
  for (const key of Reflect.ownKeys(element)) {
    if (typeof key !== "string" || !key.startsWith("__reactProps$")) continue;
    const props = Reflect.get(element, key);
    if (typeof props !== "object" || props === null) continue;
    const handler = Reflect.get(props, name);
    if (typeof handler === "function") return handler as (event: unknown) => void;
  }
  return null;
}

function click(element: ReactDomTestElement): void {
  let defaultPrevented = false;
  let propagationStopped = false;
  const event = {
    target: element,
    currentTarget: element,
    get defaultPrevented() {
      return defaultPrevented;
    },
    isPropagationStopped: () => propagationStopped,
    preventDefault: () => {
      defaultPrevented = true;
    },
    stopPropagation: () => {
      propagationStopped = true;
    },
  };

  let current: ReactDomTestElement | null = element;
  while (current && !propagationStopped) {
    event.currentTarget = current;
    reactHandler(current, "onClick")?.(event);
    current = current.parentElement;
  }

  if (defaultPrevented || element.tagName !== "BUTTON") return;
  if ((element.getAttribute("type") ?? "submit") !== "submit") return;
  let form = element.parentElement;
  while (form && form.tagName !== "FORM") form = form.parentElement;
  if (!form) return;
  event.currentTarget = form;
  reactHandler(form, "onSubmit")?.(event);
}

