}

/** Virtual collection retained after integration disconnect — no live sync link. */
export function formatDetachedSyncedCollectionType(): string {
  return DETACHED_SYNCED_COLLECTION_TYPE_LABEL;
}

/** Collection settings metadata — integration that owns the sync. */
export function formatSyncedCollectionIntegrationFieldLabel(): string {
  return "Integration";
}

/** Collection settings metadata — provider object type being synced. */
export function formatSyncedCollectionObjectFieldLabel(): string {
  return "Integration object";
}

/** Source attribution for settings, records toolbar, and record detail. */
export function formatSyncedWithIntegration(integrationName: string): string {
  const trimmed = integrationName.trim();
  return trimmed ? `Synced with ${trimmed}` : "Synced collection";
}

/** Compact collection-header badge — integration name only (e.g. Attio). */
export function formatCollectionSyncIntegrationBadge(integrationName: string): string {
  const trimmed = integrationName.trim();
  return trimmed || "Synced";
}

/** Primary enable action on the integration sync settings surface. */
export function formatTurnOnSyncAction(): string {
  return "Turn on sync";
}

export function formatStartSyncAction(): string {
  return "Start sync";
}

/** Object row primary action when sync is off or paused. */
export function formatSyncRowAction(): string {
  return "Turn on";
}

/**
 * Object row primary action when sync is already active (immediate inbound pull).
 * Outcome language — not job-control "Run now".
 */
export function formatRunNowRowAction(integrationName: string): string {
  const trimmed = integrationName.trim() || "the integration";
  return `Refresh from ${trimmed}`;
}

/** Row action while an immediate refresh is in flight. */
export function formatRunNowInProgressAction(): string {
  return "Updating…";
}

/** Stronger CTA when the object needs attention (recovery path). */
export function formatRunNowRetryAction(): string {
  return "Try updating again";
}

export function formatRunNowTooltip(objectLabel: string, integrationName: string): string {
  const object = objectLabel.trim() || "records";
  const integration = integrationName.trim() || "the integration";
  return `Pull the latest ${object} from ${integration} into this collection.`;
}

export function formatRunNowDialogTitle(objectLabel: string, integrationName: string): string {
  const object = objectLabel.trim() || "this collection";
  const integration = integrationName.trim() || "the integration";
  return `Refresh ${object} from ${integration}?`;
}

export function formatRunNowDialogDescription(
  objectLabel: string,
  integrationName: string,
): string {
  const object = objectLabel.trim() || "records";
  const integration = integrationName.trim() || "the integration";
  return `Genesis will pull the latest ${object} from ${integration} into this collection. This only updates Genesis. It doesn't send your edits back.`;
}

export function formatRefreshEnabledDialogTitle(integrationName: string): string {
  const integration = integrationName.trim() || "the integration";
  return `Refresh enabled objects from ${integration}?`;
}

export function formatRefreshEnabledDialogDescription(integrationName: string): string {
  const integration = integrationName.trim() || "the integration";
  return `Genesis will pull the latest data from ${integration} into every collection that is already turned on. This only updates Genesis. It doesn't send your edits back.`;
}

export function formatRunNowConfirmAction(integrationName: string): string {
  return formatRunNowRowAction(integrationName);
}

