useEffect(() => {
  setErrors((previous) => {
    const ids = Object.keys(previous);
    if (ids.length === 0) return previous;
    let changed = false;
    const next = { ...previous };
    for (const id of ids) {
      if (!validateAnswers(questions, draft, t)[id]) {
        delete next[id];
        changed = true;
      }
    }
    return changed ? next : previous;
  });
}, [draft, questions, t]);

