#!/usr/bin/env node
import { type SpawnSyncReturns, spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import {
  getShardFilePaths,
  getTestFilesByShard,
  TEST_SHARD_NAMES,
  type TestShardName,
} from "./test-shard-paths";

const appRoot = join(dirname(fileURLToPath(import.meta.url)), "..");

const args = process.argv.slice(2);
const runAll = args.includes("--all");

/** Parse `--part=N/M` or `N/M` (vitest-style). Defaults to the full file set. */
function parsePartSpec(argv: string[]): { part: number; parts: number } {
  for (const arg of argv) {
    const matched = /^(?:--part=)?(\d+)\/(\d+)$/.exec(arg);
    if (!matched) continue;
    const part = Number.parseInt(matched[1]!, 10);
    const parts = Number.parseInt(matched[2]!, 10);
    if (
      !Number.isFinite(part) ||
      !Number.isFinite(parts) ||
      parts < 1 ||
      part < 1 ||
      part > parts
    ) {
      console.error(`Invalid part spec: ${arg} (expected N/M with 1 <= N <= M)`);
      process.exit(1);
    }
    return { part, parts };
  }
  return { part: 1, parts: 1 };
}

const { part, parts } = parsePartSpec(args);
const shardArg = args.find((arg) => arg !== "--all" && !/^(?:--part=)?\d+\/\d+$/.test(arg));

if (!runAll && !shardArg) {
  console.error(
    `Usage: tsx scripts/run-test-shard.ts <${TEST_SHARD_NAMES.join("|")}> [N/M|--part=N/M] | --all`,
  );
  process.exit(1);
}

const shards: TestShardName[] = runAll ? [...TEST_SHARD_NAMES] : [shardArg as TestShardName];

if (!runAll && !TEST_SHARD_NAMES.includes(shards[0]!)) {
  console.error(`Unknown shard: ${shardArg}`);
  process.exit(1);
}

/**
 * Batch size limits how many files one vitest process runs.
 * Smaller batches isolate SIGSEGV/OOM crashes; larger batches avoid repeated
 * cold collect/transform cost. Set GENESIS_TEST_SHARD_BATCH_SIZE=0 for one run.
 */
function parseBatchSize(): number {
  const raw = process.env.GENESIS_TEST_SHARD_BATCH_SIZE?.trim();
  if (!raw) return 25;
  if (raw === "0" || raw.toLowerCase() === "unlimited") return Number.POSITIVE_INFINITY;
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed) || parsed < 1) return 25;
  return parsed;
}

/** Split a shard's files into equal contiguous parts (same idea as vitest --shard). */
function sliceShardPart(paths: string[], partIndex: number, partCount: number): string[] {
  if (partCount <= 1) return paths;
  const size = Math.ceil(paths.length / partCount);
  const start = size * (partIndex - 1);
  return paths.slice(start, start + size);
}

function chunkPaths(paths: string[], batchSize: number): string[][] {
  if (!Number.isFinite(batchSize) || paths.length <= batchSize) return [paths];
  const batches: string[][] = [];
  for (let offset = 0; offset < paths.length; offset += batchSize) {
    batches.push(paths.slice(offset, offset + batchSize));
  }
  return batches;
}

function processCrashed(result: SpawnSyncReturns<string>): boolean {
  if (result.error) return true;
  if (result.signal) return true;
  // Linux: SIGSEGV = 139, SIGABRT = 134
  return result.status === 139 || result.status === 134;
}

function runTestBatch(paths: string[], label: string): boolean {
