function capitalizeFirst(text: string): string {
  if (!text) return text;
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function getAskUserOptionLabels(
  question: Pick<NormalizedAskUserQuestion, "options" | "allowOther">,
): string[] {
  const labels = question.options.map((option) => option.label);
  if (question.allowOther) labels.push("Other");
  return labels;
}

function formatLabelListPlaceholder(labels: string[], conjunction: "or" | "and" = "or"): string {
  if (labels.length === 0) return "Choose one option";
  const parts = labels.map((label, index) => (index === 0 ? label : label.toLowerCase()));
  let text: string;
  if (parts.length === 1) text = parts[0] ?? "";
  else if (parts.length === 2) text = `${parts[0]} ${conjunction} ${parts[1]}`;
  else {
    const last = parts.at(-1) ?? "";
    text = `${parts.slice(0, -1).join(", ")}, ${conjunction} ${last}`;
  }
  return capitalizeFirst(text);
}

function formatAskUserOptionPlaceholder(
  question: Pick<NormalizedAskUserQuestion, "options" | "allowOther">,
): string {
  return formatLabelListPlaceholder(getAskUserOptionLabels(question));
}

function formatCheckboxSelectionSummary(
  question: NormalizedAskUserQuestion,
  selected: readonly string[],
  useOther: boolean,
): string {
  const labels = selected
    .map((value) => question.options.find((option) => option.value === value)?.label)
    .filter((label): label is string => Boolean(label));
  if (useOther) labels.push("Other");

  if (labels.length === 0) return formatAskUserOptionPlaceholder(question);

  const maxVisible = 2;
  if (labels.length > maxVisible) {
    const visible = formatLabelListPlaceholder(labels.slice(0, maxVisible), "and");
    return `${visible}, and ${labels.length - maxVisible} more`;
  }

  return formatLabelListPlaceholder(labels, "and");
}

function formatRadioSelectionSummary(
  question: NormalizedAskUserQuestion,
  draft: DraftAnswers[string],
): string {
  if (draft.useOther) return "Other";
  const value = String(draft.value || "");
  if (!value) return formatAskUserOptionPlaceholder(question);
  return question.options.find((option) => option.value === value)?.label ?? value;
}

