/**
 * Persist multi-step ask_user draft + active question in sessionStorage so
 * leave/return (same tab) restores answers. Per-tab storage keeps multi-tab
 * mixed drafts independent until durable submit.
 *
 * Also owns pure draft model helpers used by the form (build / validate / answers).
 */

import type {
  AskUserAnswer,
  AskUserQuestionType,
  NormalizedAskUserQuestion,
} from "@lib/session-ask-user";

const ASK_USER_DRAFT_KEY_PREFIX = "genesis-session-ask-user-draft-v1-";

export type AskUserDraftEntry = {
  type: AskUserQuestionType;
  value: string | string[];
  otherText: string;
  useOther: boolean;
};

export type AskUserDraftAnswers = Record<string, AskUserDraftEntry>;

export type StoredAskUserDraft = {
  requestId: string;
  questionsFingerprint: string;
  activeQuestionId: string | null;
  draft: AskUserDraftAnswers;
};

export function getAskUserDraftStorageKey(sessionId: string, requestId: string): string {
  return `${ASK_USER_DRAFT_KEY_PREFIX}${encodeURIComponent(sessionId)}-${encodeURIComponent(requestId)}`;
}

/**
 * Content-aware fingerprint so option/prompt rewrites invalidate stored drafts.
 * Ids alone are not enough when the server reuses ids with new shapes.
 */
export function fingerprintAskUserQuestions(
  questions: readonly {
    id: string;
    prompt?: string;
    type?: string;
    options?: readonly { value: string }[];
  }[],
): string {
  return questions
    .map((question) => {
      const optionValues = (question.options ?? []).map((option) => option.value).join(",");
      return `${question.id}:${question.type ?? ""}:${optionValues}:${question.prompt ?? ""}`;
    })
    .join("\0");
}

function isDraftEntry(value: unknown): value is AskUserDraftEntry {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  if (typeof record.type !== "string") return false;
  if (typeof record.otherText !== "string") return false;
  if (typeof record.useOther !== "boolean") return false;
  if (typeof record.value !== "string" && !Array.isArray(record.value)) return false;
  if (Array.isArray(record.value) && !record.value.every((item) => typeof item === "string")) {
    return false;
  }
  return true;
}

function isStoredAskUserDraft(value: unknown): value is StoredAskUserDraft {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  if (typeof record.requestId !== "string" || !record.requestId.trim()) return false;
  if (typeof record.questionsFingerprint !== "string") return false;
  if (record.activeQuestionId !== null && typeof record.activeQuestionId !== "string") return false;
  if (!record.draft || typeof record.draft !== "object" || Array.isArray(record.draft))
    return false;
  for (const entry of Object.values(record.draft as Record<string, unknown>)) {
    if (!isDraftEntry(entry)) return false;
  }
  return true;
}

export function readAskUserDraft(
  sessionId: string | null | undefined,
  requestId: string,
  questionsFingerprint: string,
  storage: Pick<Storage, "getItem"> | null = typeof sessionStorage === "undefined"
    ? null
    : sessionStorage,
): StoredAskUserDraft | null {
  if (!storage || !sessionId?.trim() || !requestId.trim()) return null;
  try {
    const raw = storage.getItem(getAskUserDraftStorageKey(sessionId, requestId));
    if (!raw) return null;
    const parsed: unknown = JSON.parse(raw);
    if (!isStoredAskUserDraft(parsed)) return null;
    if (parsed.requestId !== requestId) return null;
    if (parsed.questionsFingerprint !== questionsFingerprint) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function writeAskUserDraft(
  sessionId: string | null | undefined,
  requestId: string,
  payload: Omit<StoredAskUserDraft, "requestId">,
  storage: Pick<Storage, "setItem" | "removeItem"> | null = typeof sessionStorage === "undefined"
    ? null
    : sessionStorage,
): void {
  if (!storage || !sessionId?.trim() || !requestId.trim()) return;
  try {
    const key = getAskUserDraftStorageKey(sessionId, requestId);
    const body: StoredAskUserDraft = {
      requestId,
      questionsFingerprint: payload.questionsFingerprint,
      activeQuestionId: payload.activeQuestionId,
      draft: payload.draft,
    };
    storage.setItem(key, JSON.stringify(body));
  } catch {
    // sessionStorage may be unavailable or full.
  }
}

export function clearAskUserDraft(
  sessionId: string | null | undefined,
  requestId: string,
  storage: Pick<Storage, "removeItem"> | null = typeof sessionStorage === "undefined"
    ? null
    : sessionStorage,
): void {
  if (!storage || !sessionId?.trim() || !requestId.trim()) return;
  try {
    storage.removeItem(getAskUserDraftStorageKey(sessionId, requestId));
  } catch {
    // sessionStorage may be unavailable.
  }
}

/** Merge stored draft onto defaults so new question ids still appear. */
export function mergeAskUserDraftWithDefaults(
  defaults: AskUserDraftAnswers,
  stored: AskUserDraftAnswers | null | undefined,
): AskUserDraftAnswers {
  if (!stored) return defaults;
  const next: AskUserDraftAnswers = { ...defaults };
  for (const [id, entry] of Object.entries(stored)) {
    if (!(id in defaults)) continue;
    if (entry.type !== defaults[id]?.type) continue;
    next[id] = entry;
  }
  return next;
}

export function buildInitialAskUserDraft(
  questions: readonly NormalizedAskUserQuestion[],
): AskUserDraftAnswers {
  const draft: AskUserDraftAnswers = {};
  for (const question of questions) {
    if (question.type === "checkbox") {
      const defaults = Array.isArray(question.default) ? [...question.default] : [];
      draft[question.id] = {
        type: question.type,
        value: defaults,
        otherText: "",
        useOther: false,
      };
      continue;
    }
    if (question.type === "radio") {
      const defaultValue = typeof question.default === "string" ? question.default.trim() : "";
      const matchesOption = question.options.some((option) => option.value === defaultValue);
      if (defaultValue && !matchesOption && question.allowOther) {
        draft[question.id] = {
          type: question.type,
          value: "",
          otherText: defaultValue,
          useOther: true,
        };
      } else {
        draft[question.id] = {
          type: question.type,
          value: matchesOption ? defaultValue : "",
          otherText: "",
          useOther: false,
        };
      }
      continue;
    }
    const defaultValue = typeof question.default === "string" ? question.default : "";
    draft[question.id] = {
      type: question.type,
      value: defaultValue,
      otherText: "",
      useOther: false,
    };
  }
  return draft;
}

export function validateAskUserDraft(
  questions: readonly NormalizedAskUserQuestion[],
  draft: AskUserDraftAnswers,
): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const question of questions) {
    const entry = draft[question.id];
    if (!entry) continue;
    if (!question.required) continue;

    if (question.type === "radio") {
      if (entry.useOther) {
        if (!entry.otherText.trim()) errors[question.id] = "Enter a custom answer.";
