const OTHER_VALUE = "__other__";

const ASK_USER_PICKER_TRIGGER_CLASS =
  "flex h-9 w-full items-center justify-between gap-1.5 rounded-sm border border-input bg-muted px-3 py-2 text-sm transition-colors outline-none hover:bg-accent focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:border-red-600 dark:aria-invalid:ring-red-600/40";

const ASK_USER_PICKER_MENU_CLASS =
  "max-h-60 overflow-x-hidden overflow-y-auto overscroll-contain p-1";

type DraftAnswers = AskUserDraftAnswers;

function AskUserQuestionTitle({ question }: { question: NormalizedAskUserQuestion }) {
  return (
    <FieldTitle className="block w-full max-w-full">
      <span>
        {question.prompt}
        {question.required ? (
          <>
            <svg
              viewBox="0 0 8 8"
              className="ml-1.5 inline-block size-1.5 align-middle text-red-500"
              aria-hidden="true"
            >
              <circle cx="4" cy="4" r="3" fill="currentColor" />
            </svg>
            <span className="sr-only"> Required</span>
          </>
        ) : null}
      </span>
    </FieldTitle>
  );
}

function capitalizeFirst(text: string): string {
  if (!text) return text;
  return text.charAt(0).toUpperCase() + text.slice(1);
}

function getAskUserOptionLabels(
  question: Pick<NormalizedAskUserQuestion, "options" | "allowOther">,
): string[] {
  const labels = question.options.map((option) => option.label);
  if (question.allowOther) labels.push("Other");
  return labels;
}

function formatLabelListPlaceholder(labels: string[], conjunction: "or" | "and" = "or"): string {
  if (labels.length === 0) return "Choose one option";
  const parts = labels.map((label, index) => (index === 0 ? label : label.toLowerCase()));
  let text: string;
  if (parts.length === 1) text = parts[0] ?? "";
  else if (parts.length === 2) text = `${parts[0]} ${conjunction} ${parts[1]}`;
  else {
    const last = parts.at(-1) ?? "";
    text = `${parts.slice(0, -1).join(", ")}, ${conjunction} ${last}`;
  }
  return capitalizeFirst(text);
}

function formatAskUserOptionPlaceholder(
  question: Pick<NormalizedAskUserQuestion, "options" | "allowOther">,
): string {
  return formatLabelListPlaceholder(getAskUserOptionLabels(question));
}

function formatCheckboxSelectionSummary(
  question: NormalizedAskUserQuestion,
  selected: readonly string[],
  useOther: boolean,
): string {
  const labels = selected
    .map((value) => question.options.find((option) => option.value === value)?.label)
    .filter((label): label is string => Boolean(label));
  if (useOther) labels.push("Other");

  if (labels.length === 0) return formatAskUserOptionPlaceholder(question);

  const maxVisible = 2;
  if (labels.length > maxVisible) {
    const visible = formatLabelListPlaceholder(labels.slice(0, maxVisible), "and");
    return `${visible}, and ${labels.length - maxVisible} more`;
  }

  return formatLabelListPlaceholder(labels, "and");
}

function formatRadioSelectionSummary(
  question: NormalizedAskUserQuestion,
  draft: DraftAnswers[string],
): string {
  if (draft.useOther) return "Other";
  const value = String(draft.value || "");
  if (!value) return formatAskUserOptionPlaceholder(question);
  return question.options.find((option) => option.value === value)?.label ?? value;
}

function AskUserOptionPicker({
  open,
  onOpenChange,
  triggerLabel,
  hasSelection,
  error,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  triggerLabel: string;
  hasSelection: boolean;
  error?: string;
  children: ReactNode;
}) {
  const popupId = useId();
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          role="combobox"
          aria-controls={popupId}
          aria-expanded={open}
          aria-invalid={!!error}
          className={cn(ASK_USER_PICKER_TRIGGER_CLASS, !hasSelection && "text-muted-foreground")}
        >
          <span className="min-w-0 truncate">{triggerLabel}</span>
          <ChevronDownIcon className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </PopoverTrigger>
      <PopoverContent
        id={popupId}
        align="start"
        className="w-[var(--radix-popover-trigger-width)] gap-0 rounded-sm border border-input bg-muted p-0 shadow-md ring-0"
      >
        <div className={ASK_USER_PICKER_MENU_CLASS}>{children}</div>
      </PopoverContent>
    </Popover>
  );
}

function AskUserOtherInput({
  question,
  draft,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  onChange: (next: DraftAnswers[string]) => void;
}) {
  return (
    <Input
      value={draft.otherText}
      onChange={(event) =>
        onChange({
          ...draft,
          otherText: event.target.value,
        })
      }
      placeholder="Type your answer"
      aria-label={`${question.label} other answer`}
    />
  );
}

function AskUserCheckboxOptionRow({
  checked,
  onCheckedChange,
  children,
  align = "start",
}: {
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  children: ReactNode;
  align?: "start" | "center";
}) {
  return (
    // biome-ignore lint/a11y/noLabelWithoutControl: Radix Checkbox is the associated control
    <label
      className={cn(
        "flex min-h-11 w-full cursor-pointer gap-2 rounded-sm px-1.5 py-1 text-sm outline-none sm:min-h-10",
        align === "center" ? "items-center" : "items-start",
        "hover:bg-accent hover:[&_[data-slot=checkbox]:not([data-state=checked])]:border-foreground/25 hover:[&_[data-slot=checkbox]:not([data-state=checked])]:bg-popover hover:[&_[data-slot=radio-group-item]:not([data-state=checked])]:border-foreground/25 hover:[&_[data-slot=radio-group-item]:not([data-state=checked])]:bg-popover",
      )}
    >
      <Checkbox
        className={align === "center" ? undefined : "mt-0.5"}
        checked={checked}
        onCheckedChange={(next) => onCheckedChange(next === true)}
      />
      <div className="min-w-0 flex-1">{children}</div>
    </label>
  );
}

function AskUserCheckboxOptions({
  question,
  draft,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  onChange: (next: DraftAnswers[string]) => void;
}) {
  const selected = Array.isArray(draft.value) ? draft.value : [];

  return (
    <div data-slot="checkbox-group" className="flex w-full flex-col gap-0.5">
      {question.options.map((option) => {
        const checked = selected.includes(option.value);
        return (
          <AskUserCheckboxOptionRow
            key={option.value}
            checked={checked}
            onCheckedChange={(next) => {
              const values = new Set(selected);
              if (next) values.add(option.value);
              else values.delete(option.value);
              onChange({
                ...draft,
                value: [...values],
              });
            }}
          >
            <FieldContentCompact label={option.label} description={option.description} />
          </AskUserCheckboxOptionRow>
        );
      })}
      {question.allowOther ? (
        <AskUserCheckboxOptionRow
          checked={draft.useOther}
          align="center"
          onCheckedChange={(next) =>
            onChange({
              ...draft,
              useOther: next,
            })
          }
        >
          <span className="text-sm">Other</span>
        </AskUserCheckboxOptionRow>
      ) : null}
    </div>
  );
}

function AskUserRadioOptionRow({
  id,
  value,
  children,
  align = "start",
}: {
  id: string;
  value: string;
  children: ReactNode;
  align?: "start" | "center";
}) {
  return (
    <label
      htmlFor={id}
      className={cn(
        "flex min-h-11 w-full cursor-pointer gap-2 rounded-sm px-1.5 py-1 text-sm outline-none sm:min-h-10",
        align === "center" ? "items-center" : "items-start",
        "hover:bg-accent hover:[&_[data-slot=checkbox]:not([data-state=checked])]:border-foreground/25 hover:[&_[data-slot=checkbox]:not([data-state=checked])]:bg-popover hover:[&_[data-slot=radio-group-item]:not([data-state=checked])]:border-foreground/25 hover:[&_[data-slot=radio-group-item]:not([data-state=checked])]:bg-popover",
      )}
    >
      <RadioGroupItem id={id} value={value} className={align === "center" ? undefined : "mt-0.5"} />
      <div className="min-w-0 flex-1">{children}</div>
    </label>
  );
}

function AskUserRadioOptions({
  question,
  draft,
  onChange,
  onPick,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  onChange: (next: DraftAnswers[string]) => void;
  onPick: () => void;
}) {
  const groupId = useId();
  const selected = draft.useOther ? OTHER_VALUE : String(draft.value || "");

  return (
    <RadioGroup
      value={selected}
      onValueChange={(value) => {
        if (value === OTHER_VALUE) {
          onChange({ ...draft, useOther: true, value: "" });
        } else {
          onChange({ ...draft, useOther: false, value, otherText: "" });
        }
        onPick();
      }}
      className="flex w-full flex-col gap-0.5"
    >
      {question.options.map((option, index) => (
        <AskUserRadioOptionRow
          key={option.value}
          id={`${groupId}-option-${index}`}
          value={option.value}
        >
          <FieldContentCompact label={option.label} description={option.description} />
        </AskUserRadioOptionRow>
      ))}
      {question.allowOther ? (
        <AskUserRadioOptionRow id={`${groupId}-other`} value={OTHER_VALUE} align="center">
          <span className="text-sm">Other</span>
        </AskUserRadioOptionRow>
      ) : null}
    </RadioGroup>
  );
}

const ASK_USER_INLINE_RADIO_OPTION_LIMIT = 5;

function RadioQuestionField({
  question,
  draft,
  error,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  error?: string;
  onChange: (next: DraftAnswers[string]) => void;
}) {
  const [open, setOpen] = useState(false);
  const hasSelection = draft.useOther || Boolean(draft.value);
  const triggerLabel = formatRadioSelectionSummary(question, draft);
  const optionCount = question.options.length + (question.allowOther ? 1 : 0);
  const renderInline = optionCount > 0 && optionCount <= ASK_USER_INLINE_RADIO_OPTION_LIMIT;

  return (
    <Field data-invalid={!!error}>
      <AskUserQuestionTitle question={question} />
      {renderInline ? (
        <div className={cn(error && "rounded-sm ring-1 ring-destructive")}>
          <AskUserRadioOptions
            question={question}
            draft={draft}
            onChange={onChange}
            onPick={() => {}}
          />
        </div>
      ) : (
        <AskUserOptionPicker
          open={open}
          onOpenChange={setOpen}
          triggerLabel={triggerLabel}
          hasSelection={hasSelection}
          error={error}
        >
          <AskUserRadioOptions
            question={question}
            draft={draft}
            onChange={onChange}
            onPick={() => setOpen(false)}
          />
        </AskUserOptionPicker>
      )}
      {question.allowOther && draft.useOther ? (
        <AskUserOtherInput question={question} draft={draft} onChange={onChange} />
      ) : null}
      <FieldError>{error}</FieldError>
    </Field>
  );
}

function ConnectedIntegrationsQuestionField({
  question,
  draft,
  error,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  error?: string;
  onChange: (next: DraftAnswers[string]) => void;
}) {
  if (question.options.length === 0) {
    return (
      <Field>
        <AskUserQuestionTitle question={question} />
        <FieldDescription>
          You have not connected any apps yet.{" "}
          <Link
            to="/settings/$section"
            params={{ section: "integrations" }}
            className="text-blue-600 underline-offset-4 hover:underline"
          >
            Connect apps in Settings
          </Link>{" "}
          to include them here, or leave this blank and continue.
        </FieldDescription>
      </Field>
    );
  }

  return (
    <CheckboxQuestionField question={question} draft={draft} error={error} onChange={onChange} />
  );
}

function CheckboxQuestionField({
  question,
  draft,
  error,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  error?: string;
  onChange: (next: DraftAnswers[string]) => void;
}) {
  const [open, setOpen] = useState(false);
  const selected = Array.isArray(draft.value) ? draft.value : [];
  const hasSelection = selected.length > 0 || draft.useOther;
  const triggerLabel = formatCheckboxSelectionSummary(question, selected, draft.useOther);

  return (
    <Field data-invalid={!!error}>
      <AskUserQuestionTitle question={question} />
      <AskUserOptionPicker
        open={open}
        onOpenChange={setOpen}
        triggerLabel={triggerLabel}
        hasSelection={hasSelection}
        error={error}
      >
        <AskUserCheckboxOptions question={question} draft={draft} onChange={onChange} />
      </AskUserOptionPicker>
      {question.allowOther && draft.useOther ? (
        <AskUserOtherInput question={question} draft={draft} onChange={onChange} />
      ) : null}
      <FieldError>{error}</FieldError>
    </Field>
  );
}

function TextQuestionField({
  question,
  draft,
  error,
  onChange,
}: {
  question: NormalizedAskUserQuestion;
  draft: DraftAnswers[string];
  error?: string;
  onChange: (next: DraftAnswers[string]) => void;
}) {
  return (
    <Field data-invalid={!!error}>
      <AskUserQuestionTitle question={question} />
      <Input
        value={String(draft.value ?? "")}
        placeholder={question.placeholder}
        onChange={(event) =>
          onChange({
            ...draft,
            value: event.target.value,
          })
