  }, []);
  const visibleQuestions = useMemo(() => {
    const answerSnapshot = Object.fromEntries(
      Object.entries(draft).map(([id, entry]) => [id, { value: entry.value }]),
    );
    return baseVisibleQuestions.filter((question) =>
      isAskUserQuestionVisible(question, answerSnapshot),
    );
  }, [baseVisibleQuestions, draft]);
  const matchedActiveQuestionIndex = visibleQuestions.findIndex(
    (question) => question.id === activeQuestionId,
  );
  const activeQuestionIndex = matchedActiveQuestionIndex >= 0 ? matchedActiveQuestionIndex : 0;
  const activeQuestion = visibleQuestions[activeQuestionIndex];

  // biome-ignore lint/correctness/useExhaustiveDependencies: reset form chrome when draft identity changes
  useEffect(() => {
    autoSubmittedRef.current = false;
    setErrors({});
    setDispatchError(null);
    setFocusQuestionId(null);
  }, [draftResetKey]);

  useEffect(() => {
    const nextActiveQuestionId = activeQuestion?.id ?? null;
    if (activeQuestionId === nextActiveQuestionId) return;
    setActiveQuestionId(nextActiveQuestionId);
  }, [activeQuestion?.id, activeQuestionId, setActiveQuestionId]);

  const submitImplicitAnswers = useCallback(async () => {
    if (!onSubmit) return;
    autoSubmittedRef.current = true;
    autoSubmittedAskUserRequestIds.add(request.requestId);
    setSubmitting(true);
    try {
      const result = await awaitSessionCommandDispatch(
        onSubmit({
          requestId: request.requestId,
          cancelled: false,
          answers: implicitAnswers,
        }),
      );
      if (!result.ok) {
        throw new Error(result.message?.trim() || saveAnswersError);
      }
    } catch (error) {
      autoSubmittedRef.current = false;
      autoSubmittedAskUserRequestIds.delete(request.requestId);
      setDispatchError(error instanceof Error ? error.message : saveAnswersError);
    } finally {
      setSubmitting(false);
    }
  }, [implicitAnswers, onSubmit, request.requestId, saveAnswersError, setSubmitting]);

  useEffect(() => {
    if (resolution || !onSubmit || autoSubmittedRef.current) return;
    if (visibleQuestions.length > 0) return;
    if (implicitAnswers.length === 0) return;
    if (autoSubmittedAskUserRequestIds.has(request.requestId)) return;
    void submitImplicitAnswers();
  }, [
    implicitAnswers.length,
    onSubmit,
    request.requestId,
    resolution,
    submitImplicitAnswers,
    visibleQuestions.length,
  ]);

  const previewSummary = useMemo(() => {
    const questionsForPreview =
      visibleQuestions.length > 1
        ? visibleQuestions.slice(activeQuestionIndex, activeQuestionIndex + 1)
        : visibleQuestions;
    const answers = [
      ...(visibleQuestions.length > 1 ? [] : implicitAnswers),
      ...draftToAskUserAnswers(questionsForPreview, draft),
    ];
    const summary = formatAskUserResultSummary(request, {
      requestId: request.requestId,
      cancelled: false,
      answers,
    });
    return announceAskUserDraftSummary(summary);
  }, [activeQuestionIndex, draft, implicitAnswers, request, visibleQuestions]);

  if (resolution) {
    return (
      <SessionAskUserReceipt
        request={request}
        result={resolution}
        className={className}
        sessionId={sessionId}
        defaultExpanded={defaultExpanded}
      />
    );
  }

  if (visibleQuestions.length === 0) {
    return dispatchError ? (
      <TurnChromeCard
        state="gold"
        className={className}
        icon={<MessageCircleQuestion className="size-4 shrink-0" aria-hidden="true" />}
        title={request.title?.trim() || "A few questions"}
      >
        <div className="flex items-center justify-between gap-3 px-3 py-2">
          <p className="text-sm text-destructive">{dispatchError}</p>
          <Button
            type="button"
            size="sm"
            variant="outline"
            onClick={() => {
              setDispatchError(null);
              void submitImplicitAnswers();
            }}
          >
            {t("actions.retry")}
          </Button>
        </div>
      </TurnChromeCard>
    ) : null;
  }

  const updateQuestion = (questionId: string, next: DraftAnswers[string]) => {
    setDraft((previous) => ({ ...previous, [questionId]: next }));
    setErrors((previous) => {
      if (!previous[questionId]) return previous;
      const copy = { ...previous };
      delete copy[questionId];
      return copy;
    });
  };

  const goToQuestion = (index: number) => {
    const question = visibleQuestions[index];
    if (!question) return;
    setFocusQuestionId(question.id);
    setActiveQuestionId(question.id);
  };

  const handleSubmit = () => {
    if (submitting) return;
    const nextErrors = validateAskUserDraft(visibleQuestions, draft);
    setErrors(nextErrors);
    const firstInvalidQuestionIndex = visibleQuestions.findIndex(
      (question) => nextErrors[question.id],
    );
    if (firstInvalidQuestionIndex >= 0) {
      goToQuestion(firstInvalidQuestionIndex);
      return;
    }
    if (!onSubmit) return;
    setSubmitting(true);
    setDispatchError(null);
    // Keep sessionStorage draft until durable resolution; clear only on success path via resolution.
    void (async () => {
      try {
        const result = await awaitSessionCommandDispatch(
          onSubmit({
            requestId: request.requestId,
            cancelled: false,
            answers: [...implicitAnswers, ...draftToAskUserAnswers(visibleQuestions, draft)],
          }),
        );
        if (!result.ok) {
          setDispatchError(result.message?.trim() || saveAnswersError);
        }
      } catch (error) {
        setDispatchError(error instanceof Error ? error.message : saveAnswersError);
      } finally {
        setSubmitting(false);
      }
    })();
  };

  const handleCancel = () => {
    if (submitting) return;
    if (!onCancel) return;
    setSubmitting(true);
    setDispatchError(null);
    void (async () => {
      try {
        const result = await awaitSessionCommandDispatch(onCancel());
        if (!result.ok) {
          setDispatchError(result.message?.trim() || cancelQuestionsError);
        }
      } catch (error) {
        setDispatchError(error instanceof Error ? error.message : cancelQuestionsError);
      } finally {
        setSubmitting(false);
      }
    })();
  };

  const isMultiStep = visibleQuestions.length > 1;
  const isLastQuestion = activeQuestionIndex === visibleQuestions.length - 1;

  const handleContinue = () => {
    if (!activeQuestion) return;
    const nextErrors = validateAskUserDraft([activeQuestion], draft);
    setErrors((previous) => ({ ...previous, ...nextErrors }));
    if (Object.keys(nextErrors).length > 0) return;
    goToQuestion(Math.min(activeQuestionIndex + 1, visibleQuestions.length - 1));
  };

  const handlePrimaryAction = () => {
    if (isMultiStep && !isLastQuestion) {
      handleContinue();
      return;
    }
    handleSubmit();
  };

  const renderQuestion = (question: NormalizedAskUserQuestion) => {
    const entry = draft[question.id];
    if (!entry) return null;
    const error = errors[question.id];

    if (question.type === "radio") {
      return (
        <RadioQuestionField
          question={question}
          draft={entry}
          error={error}
          onChange={(next) => updateQuestion(question.id, next)}
        />
      );
    }

    if (question.type === "checkbox") {
      if (question.id === AUTOMATION_SETUP_CONNECTED_INTEGRATIONS_QUESTION_ID) {
        return (
          <ConnectedIntegrationsQuestionField
            question={question}
            draft={entry}
            error={error}
            onChange={(next) => updateQuestion(question.id, next)}
          />
        );
      }
      return (
        <CheckboxQuestionField
          question={question}
          draft={entry}
          error={error}
          onChange={(next) => updateQuestion(question.id, next)}
        />
      );
    }

    return (
      <TextQuestionField
        question={question}
        draft={entry}
        error={error}
        onChange={(next) => updateQuestion(question.id, next)}
      />
    );
  };

  return (
    <TurnChromeCard
      as="form"
      state="gold"
      className={className}
      icon={
        <MessageCircleQuestion
          className={cn("size-4 shrink-0", workBlockIconClass("gold"))}
          aria-hidden="true"
        />
      }
      title={request.title?.trim() || "A few questions"}
      description={request.description ?? undefined}
      headerActions={
        isMultiStep ? (
          <AskUserStepProgress current={activeQuestionIndex + 1} total={visibleQuestions.length} />
        ) : undefined
      }
      onSubmit={(event) => {
        event.preventDefault();
        handlePrimaryAction();
      }}
      footer={
        <div className="flex w-full flex-col gap-1.5">
          <div className="flex items-center gap-2">
            <Button type="submit" size="sm" disabled={submitting}>
              {submitting
                ? t("askUser.saving")
                : isMultiStep && !isLastQuestion
                  ? "Continue"
                  : "Submit"}
            </Button>
            {isMultiStep && activeQuestionIndex > 0 ? (
              <Button
                type="button"
                size="sm"
                variant="ghost"
                disabled={submitting}
                onClick={() => goToQuestion(activeQuestionIndex - 1)}
              >
                Back
              </Button>
            ) : null}
            <Button
              type="button"
              size="sm"
              variant="ghost"
              className={cn(isMultiStep && "ml-auto")}
              disabled={submitting}
              onClick={handleCancel}
            >
              Cancel
            </Button>
          </div>
          {dispatchError ? <p className="text-xs text-destructive">{dispatchError}</p> : null}
        </div>
      }
      footerClassName="pt-0"
    >
      <div className="px-3 pt-1 pb-2">
        <AnimatePresence initial={false} mode="wait">
          {activeQuestion ? (
            <AskUserQuestionPanel
              key={activeQuestion.id}
              questionId={activeQuestion.id}
              focusQuestionId={focusQuestionId}
              onFocusHandled={handleQuestionFocus}
              ariaLabel={
                isMultiStep
                  ? `Question ${activeQuestionIndex + 1} of ${visibleQuestions.length}`
                  : undefined
