): string[] {
  const labels = question.options.map((option) => option.label);
  if (question.allowOther) labels.push(t("askUser.other"));
  return labels;
}

function formatLabelListPlaceholder(
  labels: string[],
  t: TFunction<"sessions">,
  conjunction: "or" | "and" = "or",
): string {
  if (labels.length === 0) return t("askUser.chooseOne");
  const joiner = t(`askUser.conjunction.${conjunction}`);
  let text: string;
  if (labels.length === 1) text = labels[0] ?? "";
  else if (labels.length === 2) text = `${labels[0]} ${joiner} ${labels[1]}`;
  else {
    const last = labels.at(-1) ?? "";
    text = `${labels.slice(0, -1).join(", ")}, ${joiner} ${last}`;
  }
  return capitalizeFirst(text);
}

function formatAskUserOptionPlaceholder(
  question: Pick<NormalizedAskUserQuestion, "options" | "allowOther">,
  t: TFunction<"sessions">,
): string {
  return formatLabelListPlaceholder(getAskUserOptionLabels(question, t), t);
}

function formatCheckboxSelectionSummary(
  question: NormalizedAskUserQuestion,
  selected: readonly string[],
  useOther: boolean,
  t: TFunction<"sessions">,
): string {
  const labels = selected
    .map((value) => question.options.find((option) => option.value === value)?.label)
    .filter((label): label is string => Boolean(label));
  if (useOther) labels.push(t("askUser.other"));

  if (labels.length === 0) return formatAskUserOptionPlaceholder(question, t);

  const maxVisible = 2;
  if (labels.length > maxVisible) {
    const visible = formatLabelListPlaceholder(labels.slice(0, maxVisible), t, "and");
    return t("askUser.moreSelected", {
      visible,
      count: labels.length - maxVisible,
    });
  }

  return formatLabelListPlaceholder(labels, t, "and");
}

function formatRadioSelectionSummary(
  question: NormalizedAskUserQuestion,
  draft: DraftAnswers[string],
  t: TFunction<"sessions">,
): string {
  if (draft.useOther) return t("askUser.other");
  const value = String(draft.value || "");
  if (!value) return formatAskUserOptionPlaceholder(question, t);
  return question.options.find((option) => option.value === value)?.label ?? value;
}

