import {
  SESSION_ASK_USER_FIXTURE_MIXED,
  SESSION_ASK_USER_FIXTURE_RADIO,
} from "@lib/session-ask-user";
import "@web/i18n";
import {
  installReactDomTestEnvironment,
  mountReactNode,
  ReactDomTestElement,
  unmountReactNode,
} from "@web/components/__tests__/react-dom-test-environment";
import { act } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { afterAll, beforeAll, describe, expect, test } from "vitest";
import { SessionAskUserForm } from "./session-ask-user-form";

type TestEnvironment = ReturnType<typeof installReactDomTestEnvironment>;

let testEnvironment: TestEnvironment | null = null;
let htmlFormElementDescriptor: PropertyDescriptor | undefined;

function findElements(
  root: ReactDomTestElement,
  predicate: (element: ReactDomTestElement) => boolean,
): ReactDomTestElement[] {
  const matches = predicate(root) ? [root] : [];
  for (const child of root.children) matches.push(...findElements(child, predicate));
  return matches;
}

function reactHandler(element: ReactDomTestElement, name: "onClick" | "onSubmit") {
  for (const key of Reflect.ownKeys(element)) {
    if (typeof key !== "string" || !key.startsWith("__reactProps$")) continue;
    const props = Reflect.get(element, key);
    if (typeof props !== "object" || props === null) continue;
    const handler = Reflect.get(props, name);
    if (typeof handler === "function") return handler as (event: unknown) => void;
  }
  return null;
}

function click(element: ReactDomTestElement): void {
  let defaultPrevented = false;
  let propagationStopped = false;
  const event = {
    target: element,
    currentTarget: element,
    get defaultPrevented() {
      return defaultPrevented;
    },
    isPropagationStopped: () => propagationStopped,
    preventDefault: () => {
      defaultPrevented = true;
    },
    stopPropagation: () => {
      propagationStopped = true;
    },
  };

  let current: ReactDomTestElement | null = element;
  while (current && !propagationStopped) {
    event.currentTarget = current;
    reactHandler(current, "onClick")?.(event);
    current = current.parentElement;
  }

  if (defaultPrevented || element.tagName !== "BUTTON") return;
  if ((element.getAttribute("type") ?? "submit") !== "submit") return;
  let form = element.parentElement;
  while (form && form.tagName !== "FORM") form = form.parentElement;
  if (!form) return;
  event.currentTarget = form;
  reactHandler(form, "onSubmit")?.(event);
}

function setReducedMotion(value: boolean): void {
  if (!testEnvironment) throw new Error("Test environment is not installed.");
  const testWindow = testEnvironment.document.defaultView as {
    matchMedia?: (query: string) => MediaQueryList;
  };
  testWindow.matchMedia = ((query: string) => ({
    matches: value,
    media: query,
    onchange: null,
    addListener: () => {},
    removeListener: () => {},
    addEventListener: () => {},
    removeEventListener: () => {},
    dispatchEvent: () => true,
  })) as (query: string) => MediaQueryList;
}

beforeAll(() => {
  testEnvironment = installReactDomTestEnvironment();
  class TestHtmlInputElement {
    private testChecked = false;

    get checked(): boolean {
      return this.testChecked;
    }

    set checked(value: boolean) {
      this.testChecked = value;
    }
  }
  (testEnvironment.document.defaultView as Record<string, unknown>).HTMLInputElement =
    TestHtmlInputElement;
  htmlFormElementDescriptor = Object.getOwnPropertyDescriptor(globalThis, "HTMLFormElement");
  Object.defineProperty(globalThis, "HTMLFormElement", {
    configurable: true,
    value: ReactDomTestElement,
  });
  const document = testEnvironment.document;
  const createElement = document.createElement.bind(document);
  document.createElement = (name: string) => {
    const element = createElement(name);
    (element.style as Record<string, unknown>).setProperty = (property: string, value: string) => {
      element.style[property] = value;
    };
    return element;
  };
});

afterAll(() => {
  testEnvironment?.restore();
  if (htmlFormElementDescriptor) {
    Object.defineProperty(globalThis, "HTMLFormElement", htmlFormElementDescriptor);
  } else {
    Reflect.deleteProperty(globalThis, "HTMLFormElement");
  }
  testEnvironment = null;
});

describe("SessionAskUserForm steps", () => {
  test("keeps a single question compact", () => {
    const html = renderToStaticMarkup(
      <SessionAskUserForm request={SESSION_ASK_USER_FIXTURE_RADIO} />,
    );

    expect(html).toContain("Which format should I use for the final answer?");
    expect(html).toContain('<circle cx="4" cy="4" r="3"');
    expect(html).toContain("Required");
    expect(html).toContain('data-chrome-presentation="dialog"');
    expect(html).not.toContain("answer? *");
    expect(html).toContain(">Submit<");
    expect(html).not.toContain(">Continue<");
    expect(html).not.toContain("1 of 1");
  });

  test("shows one question and progress for a multi-question request", () => {
    const html = renderToStaticMarkup(
      <SessionAskUserForm request={SESSION_ASK_USER_FIXTURE_MIXED} />,
