    expect(html).toContain('role="progressbar"');
    expect(html).toContain('aria-valuenow="1"');
    expect(html).toContain("What matters most for this pass?");
    expect(html).not.toContain("Which channels should I include?");
    expect(html).not.toContain("Anything else I should know?");
    expect(html.match(/data-slot="field"/g)).toHaveLength(1);
    expect(html).toContain(">Continue<");
    expect(html).not.toContain(">Back<");
  });

