      await act(async () => click(continueButton as ReactDomTestElement));

      expect(mounted.container.textContent).toContain("Which channels should I include?");
      const backButton = findElements(
        mounted.container,
        (element) => element.tagName === "BUTTON" && element.textContent === "Back",
      )[0];
      expect(backButton).toBeDefined();

      await act(async () => click(backButton as ReactDomTestElement));

      expect(mounted.container.textContent).toContain("What matters most for this pass?");
      const restoredSpeed = findElements(
        mounted.container,
        (element) =>
          element.getAttribute("role") === "radio" && element.getAttribute("value") === "speed",
      )[0];
      expect(restoredSpeed?.getAttribute("data-state")).toBe("checked");
    } finally {
      await unmountReactNode(mounted.root);
    }
  });

  test("rapid navigation focuses only the final mounted question", async () => {
    if (!testEnvironment) throw new Error("Test environment is not installed.");
    setReducedMotion(false);
    const mounted = await mountReactNode(
      testEnvironment.document,
      <SessionAskUserForm request={SESSION_ASK_USER_FIXTURE_MIXED} />,
    );

    try {
      const speed = findElements(
        mounted.container,
        (element) =>
          element.getAttribute("role") === "radio" && element.getAttribute("value") === "speed",
      )[0];
      const continueButton = findElements(
        mounted.container,
        (element) => element.tagName === "BUTTON" && element.textContent === "Continue",
      )[0];
      await act(async () => click(speed as ReactDomTestElement));
      await act(async () => click(continueButton as ReactDomTestElement));

      const backButton = findElements(
        mounted.container,
        (element) => element.tagName === "BUTTON" && element.textContent === "Back",
      )[0];
      await act(async () => click(backButton as ReactDomTestElement));
      await act(async () => new Promise((resolve) => setTimeout(resolve, 220)));

      expect(mounted.container.textContent).toContain("What matters most for this pass?");
      expect(testEnvironment.document.activeElement?.getAttribute("aria-label")).toBe(
        "Question 1 of 3",
      );
    } finally {
      await unmountReactNode(mounted.root);
    }
  });

  test("shows the dispatch message when submit returns ok false", async () => {
    if (!testEnvironment) throw new Error("Test environment is not installed.");
    const mounted = await mountReactNode(
      testEnvironment.document,
      <SessionAskUserForm
        request={SESSION_ASK_USER_FIXTURE_RADIO}
        onSubmit={() => ({ ok: false, message: "The answer was not saved." })}
      />,
    );

    try {
      const choice = findElements(
        mounted.container,
        (element) =>
          element.getAttribute("role") === "radio" && element.getAttribute("value") === "concise",
      )[0];
      const submit = findElements(
        mounted.container,
        (element) => element.tagName === "BUTTON" && element.textContent === "Submit",
      )[0];
      await act(async () => click(choice as ReactDomTestElement));
      await act(async () => click(submit as ReactDomTestElement));
      expect(mounted.container.textContent).toContain("The answer was not saved.");
    } finally {
      await unmountReactNode(mounted.root);
    }
