function DeviceIcon({ modality }: { modality: string }) {
  const value = modality.trim().toLowerCase();
  if (value === "mobile") return <Smartphone className="size-4 shrink-0 text-muted-foreground" />;
  if (value === "desktop") return <Laptop className="size-4 shrink-0 text-muted-foreground" />;
  return <MonitorSmartphone className="size-4 shrink-0 text-muted-foreground" />;
}

function SecurityStatusBadge({ enabled }: { enabled: boolean }) {
  return (
    <Badge
      variant="outline"
      className={cn(
        "h-5 shrink-0 px-1.5 text-[11px] font-medium capitalize",
        enabled
          ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300"
          : "border-destructive/30 bg-destructive/10 text-destructive",
      )}
    >
      {enabled ? "Enabled" : "Disabled"}
    </Badge>
  );
}

function DeviceSessionRow({
  session,
  revokingId,
  onRevoke,
}: {
  session: DeviceSession;
  revokingId: string | null;
  onRevoke: (session: DeviceSession) => Promise<void>;
}) {
