  const [expanded, setExpanded] = useState(session.isCurrent);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const title = summarizeUserAgent(session.userAgent);
  const modalityLabel = formatDeviceModality(session.modality);
  const location = formatDeviceLocationLabel(session.locationLabel, session.location);
  const authMethod = formatDeviceAuthMethod(session.authMethod);
  const isRevoking = revokingId === session.id;

  return (
    <div className={cn(settingsListRowClassName, "px-4 py-3")}>
      <div className="flex items-start gap-3">
        <div className="mt-0.5">
          <DeviceIcon modality={session.modality} />
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-3">
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-2">
                <p className="text-sm font-medium">{title}</p>
                {session.isCurrent ? (
                  <Badge
                    variant="outline"
                    className="border-primary/30 bg-primary/10 text-[11px] text-primary"
                  >
                    This device
                  </Badge>
                ) : null}
              </div>
              <p className="mt-0.5 text-xs text-muted-foreground">
                {modalityLabel}
                {location ? ` · ${location}` : ""}
                {" · "}
                {t("security.devices.active", {
                  date: formatRelativeTime(session.lastSeenAt, Date.now(), locale, unavailable),
                })}
              </p>
            </div>
            <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
              <AlertDialogTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="h-7 shrink-0 border-destructive/40 text-xs text-destructive hover:bg-destructive/10 hover:text-destructive"
                  disabled={isRevoking}
                >
                  {isRevoking ? (
                    <>
                      <Loader2 className="size-3.5 animate-spin" />
                      Signing out…
                    </>
                  ) : (
                    "Force log out"
                  )}
                </Button>
              </AlertDialogTrigger>
              <AlertDialogContent>
                <AlertDialogHeader>
                  <AlertDialogTitle>
                    {session.isCurrent ? "Sign out of this device?" : "Force log out this device?"}
                  </AlertDialogTitle>
                  <AlertDialogDescription>
                    {session.isCurrent
                      ? "You'll be signed out of Genesis on this device right away. Sign in again to continue."
                      : "That device will be signed out of Genesis immediately. Anyone using it will need to sign in again."}
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel disabled={isRevoking}>Cancel</AlertDialogCancel>
                  <AlertDialogAction
                    className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                    disabled={isRevoking}
                    onClick={(event) => {
                      event.preventDefault();
                      void (async () => {
                        await onRevoke(session);
                        setConfirmOpen(false);
                      })();
                    }}
                  >
                    {session.isCurrent ? "Sign out" : "Force log out"}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          </div>
          <div className="mt-2">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-7 px-2 text-xs"
              onClick={() => setExpanded((open) => !open)}
              aria-expanded={expanded}
            >
              {expanded ? "Hide details" : "Show details"}
              <ChevronDown
                className={cn("ml-1 size-3.5 transition-transform", expanded && "rotate-180")}
              />
            </Button>
          </div>
          {expanded ? (
            <dl className="mt-3 grid gap-2 rounded-md border border-border/60 bg-muted/20 px-3 py-3 text-xs sm:grid-cols-2">
              <div>
                <dt className="text-muted-foreground">Signed in</dt>
                <dd className="mt-0.5 font-medium">
                  {formatAbsoluteTime(session.startedAt, locale, unavailable)}
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">Last active</dt>
                <dd className="mt-0.5 font-medium">
                  {formatAbsoluteTime(session.lastSeenAt, locale, unavailable)}
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">IP address</dt>
                <dd className="mt-0.5 font-medium">
                  {session.ipAddress?.trim() || "Not available"}
                </dd>
              </div>
              <div>
                <dt className="text-muted-foreground">Location</dt>
                <dd className="mt-0.5 font-medium">{location || "Not available"}</dd>
              </div>
              <div>
                <dt className="text-muted-foreground">Sign-in method</dt>
                <dd className="mt-0.5 font-medium">{authMethod || "Not available"}</dd>
              </div>
              <div className="sm:col-span-2">
                <dt className="text-muted-foreground">Browser details</dt>
                <dd className="mt-0.5 break-all font-medium text-muted-foreground">
                  {session.userAgent?.trim() || "Not available"}
                </dd>
              </div>
            </dl>
          ) : null}
        </div>
      </div>
    </div>
  );
}

function DevicesListSkeleton() {
  return (
    <div className={settingsCardClassName}>
      {[0, 1].map((key) => (
        <div key={key} className={cn(settingsListRowClassName, "px-4 py-3")}>
          <div className="flex items-start gap-3">
            <Skeleton className="mt-0.5 size-4 rounded-sm" />
            <div className="min-w-0 flex-1 space-y-2">
              <Skeleton className="h-4 w-48" />
              <Skeleton className="h-3 w-64 max-w-full" />
              <Skeleton className="h-7 w-28" />
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export function SecuritySettings() {
  const { t, i18n } = useTranslation("settings");
  const locale = i18n.resolvedLanguage ?? i18n.language;
  const unavailable = t("security.devices.notAvailable");
  const { logout } = useSession();
  const { status, loading: statusLoading, refresh: refreshStatus } = useSecurityStatus();
  const { passkeys, loading: passkeysLoading, refresh: refreshPasskeys } = useSecurityPasskeys();
  const registerPasskey = useRegisterPasskeyMutation();
  const deletePasskey = useDeletePasskeyMutation();
  const disableTotp = useTotpDisableMutation();
  const regenerateRecovery = useTotpRegenerateRecoveryMutation();

  const {
    sessions,
    loading: devicesLoading,
    error: devicesError,
    refresh: refreshDevices,
  } = useSettingsDevices();
  const revokeMutation = useRevokeDeviceSessionMutation();
  const [revokingId, setRevokingId] = useState<string | null>(null);

  const [totpSetupOpen, setTotpSetupOpen] = useState(false);
  const [disableCode, setDisableCode] = useState("");
  const [disableOpen, setDisableOpen] = useState(false);
  const [regenCode, setRegenCode] = useState("");
  const [regenOpen, setRegenOpen] = useState(false);
  const [newRecoveryCodes, setNewRecoveryCodes] = useState<string[] | null>(null);
  const [addingPasskey, setAddingPasskey] = useState(false);

  const handleRevoke = useCallback(
    async (session: DeviceSession) => {
      setRevokingId(session.id);
      try {
        const result = await revokeMutation.mutateAsync(session.id);
        if (result.isCurrent || session.isCurrent) {
          toast.success("Signed out of this device");
          await logout({ redirect: true });
          return;
        }
        toast.success("Device signed out");
        await refreshDevices();
      } catch (err) {
        console.error("[security-settings] Failed to force log out device", err);
        toast.error("Could not sign out that device. Try again.");
      } finally {
        setRevokingId(null);
      }
    },
    [logout, refreshDevices, revokeMutation],
  );

  const handleAddPasskey = useCallback(async () => {
    setAddingPasskey(true);
    try {
      await registerPasskey.mutateAsync(undefined);
      toast.success("Passkey added");
      await refreshPasskeys();
      await refreshStatus();
    } catch (err) {
      const message = err instanceof Error ? err.message : "Could not add passkey.";
      if (/not allowed|cancel|abort/i.test(message)) {
        toast.message("Passkey setup cancelled");
      } else {
        toast.error(message);
      }
    } finally {
      setAddingPasskey(false);
    }
  }, [registerPasskey, refreshPasskeys, refreshStatus]);

  const handleDeletePasskey = useCallback(
    async (id: string) => {
      try {
        await deletePasskey.mutateAsync(id);
        toast.success("Passkey removed");
        await refreshPasskeys();
        await refreshStatus();
      } catch (err) {
        toast.error(err instanceof Error ? err.message : "Could not remove passkey.");
      }
    },
    [deletePasskey, refreshPasskeys, refreshStatus],
  );

  const handleDisableTotp = useCallback(async () => {
    try {
      await disableTotp.mutateAsync(disableCode);
      toast.success("Authenticator app turned off");
      setDisableOpen(false);
      setDisableCode("");
      await refreshStatus();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Could not turn off authenticator.");
    }
  }, [disableCode, disableTotp, refreshStatus]);

  const handleRegen = useCallback(async () => {
    try {
      const result = await regenerateRecovery.mutateAsync(regenCode);
      setNewRecoveryCodes(result.recoveryCodes);
      setRegenCode("");
      toast.success("New recovery codes ready");
      await refreshStatus();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Could not create new recovery codes.");
    }
  }, [regenCode, regenerateRecovery, refreshStatus]);

  const browserHasPasskeyApi =
    typeof window !== "undefined" && typeof window.PublicKeyCredential !== "undefined";
  const hostSupport = getBrowserWebauthnHostSupport();
  const passkeySupported = browserHasPasskeyApi && hostSupport.supported;

  return (
    <SettingsSection>
      <SettingsSectionHeader
        title="Security"
        description="Keep your Genesis account safe."
        action={
          <SettingsHelpPopover
            title="How Security works"
            description="Protect your account and control where you are signed in."
            steps={[
              "Add a passkey or authenticator for stronger sign-in.",
              "Review Devices to see where you are signed in.",
              "Sign out any device you do not recognize.",
            ]}
          />
        }
      />

      <div className="space-y-3">
        <div>
          <h3 className="text-sm font-medium">Additional Security</h3>
          <p className="mt-1 text-xs text-muted-foreground">
            Set up additional ways to secure your account.
          </p>
        </div>

        {/* Passkeys */}
        <div className={cn(settingsCardClassName, "p-4")}>
          <div className="flex items-start justify-between gap-3">
            <div className="flex min-w-0 flex-1 items-start gap-3">
              <Fingerprint className="mt-0.5 size-5 shrink-0 text-muted-foreground" />
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="text-sm font-medium">Passkeys</p>
                  {statusLoading || passkeysLoading ? (
                    <Skeleton className="h-5 w-16" />
                  ) : (
                    <SecurityStatusBadge enabled={passkeys.length > 0} />
                  )}
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  Sign in faster with Face ID, Touch ID, or your device unlock — no email code
                  needed.
                </p>
                {statusLoading || passkeysLoading ? (
                  <Skeleton className="mt-2 h-4 w-32" />
                ) : (
                  <p className="mt-2 text-xs text-muted-foreground">
                    {passkeys.length === 0
                      ? "No passkeys yet"
                      : `${passkeys.length} passkey${passkeys.length === 1 ? "" : "s"}`}
                  </p>
                )}
              </div>
            </div>
            <div className="flex min-w-[5.5rem] shrink-0 justify-end">
              <Button
                type="button"
                size="sm"
                className="min-w-[5.5rem]"
                onClick={() => void handleAddPasskey()}
                disabled={addingPasskey || !passkeySupported}
              >
                {addingPasskey ? (
                  <>
                    <Loader2 className="size-3.5 animate-spin" />
                    Waiting…
                  </>
                ) : (
                  "Set up"
                )}
              </Button>
            </div>
          </div>
          {!browserHasPasskeyApi ? (
            <p className="mt-3 text-xs text-muted-foreground">
              This browser doesn’t support passkeys.
            </p>
          ) : !hostSupport.supported ? (
            <p className="mt-3 text-xs text-muted-foreground">
              {hostSupport.message}{" "}
              {hostSupport.localhostUrl ? (
                <a
                  href={hostSupport.localhostUrl}
                  className="font-medium text-foreground underline-offset-2 hover:underline"
                >
                  Open localhost
                </a>
              ) : null}
            </p>
          ) : null}
          {passkeys.length > 0 ? (
            <ul className="mt-4 divide-y divide-border/60 border-t border-border/60">
              {passkeys.map((pk) => (
                <li
                  key={pk.id}
                  className="flex flex-wrap items-center justify-between gap-2 py-3 text-sm"
                >
                  <div>
                    <p className="font-medium">{pk.label}</p>
                    <p className="text-xs text-muted-foreground">
                      {t("security.passkeys.addedAt", {
                        date: formatAbsoluteTime(pk.createdAt, locale, unavailable),
                      })}
                      {pk.lastUsedAt
                        ? ` · ${t("security.passkeys.lastUsed", {
                            date: formatRelativeTime(
                              pk.lastUsedAt,
                              Date.now(),
                              locale,
                              unavailable,
                            ),
                          })}`
                        : ""}
                    </p>
                  </div>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        className="h-7 border-destructive/40 text-xs text-destructive"
                      >
                        Remove
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>Remove this passkey?</AlertDialogTitle>
                        <AlertDialogDescription>
                          You won’t be able to use it to sign in anymore. You can always add a new
                          one.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                          onClick={(e) => {
                            e.preventDefault();
                            void handleDeletePasskey(pk.id);
                          }}
                        >
                          Remove
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </li>
              ))}
            </ul>
          ) : null}
        </div>

        {/* Authenticator */}
        <div className={cn(settingsCardClassName, "p-4")}>
          <div className="flex items-start justify-between gap-3">
            <div className="flex min-w-0 flex-1 items-start gap-3">
              <Shield className="mt-0.5 size-5 shrink-0 text-muted-foreground" />
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2">
                  <p className="text-sm font-medium">Authenticator app</p>
                  {statusLoading ? (
                    <Skeleton className="h-5 w-16" />
                  ) : (
                    <SecurityStatusBadge enabled={Boolean(status?.totpEnabled)} />
                  )}
                </div>
                <p className="mt-0.5 text-xs text-muted-foreground">
                  Add a second step after your email code (or Google sign-in) with a code from an
                  app like Google Authenticator or 1Password.
                </p>
                {statusLoading ? (
                  <Skeleton className="mt-2 h-4 w-40" />
                ) : status?.totpEnabled ? (
                  <p className="mt-2 text-xs text-muted-foreground">
                    {status.totpEnabledAt
                      ? t("security.authenticator.since", {
                          date: formatAbsoluteTime(status.totpEnabledAt, locale, unavailable),
                        })
                      : "On"}
                    {typeof status.recoveryCodesRemaining === "number"
                      ? ` · ${status.recoveryCodesRemaining} recovery code${status.recoveryCodesRemaining === 1 ? "" : "s"} left`
                      : ""}
                  </p>
                ) : null}
              </div>
            </div>
            <div className="flex min-w-[5.5rem] shrink-0 flex-wrap items-start justify-end gap-2">
              {status?.totpEnabled ? (
                <>
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    onClick={() => setRegenOpen(true)}
                  >
                    <KeyRound className="size-3.5" />
                    New recovery codes
                  </Button>
                  <Button
                    type="button"
                    size="sm"
                    variant="outline"
                    className="border-destructive/40 text-destructive"
                    onClick={() => setDisableOpen(true)}
                  >
                    Turn off
                  </Button>
                </>
              ) : (
                <Button
                  type="button"
                  size="sm"
                  className="min-w-[5.5rem]"
                  onClick={() => setTotpSetupOpen(true)}
                >
                  Set up
                </Button>
              )}
            </div>
          </div>
        </div>

        <TotpSetupDialog
          open={totpSetupOpen}
          onOpenChange={setTotpSetupOpen}
          onComplete={() => {
            void refreshStatus();
          }}
        />

        {/* Disable TOTP dialog */}
        <AlertDialog open={disableOpen} onOpenChange={setDisableOpen}>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Turn off authenticator app?</AlertDialogTitle>
              <AlertDialogDescription>
                You’ll only need your email code or Google to sign in. Enter a code from your app or
                a recovery code to confirm.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <div className="space-y-2 py-2">
              <Label htmlFor="totp-disable-code">Code</Label>
              <Input
                id="totp-disable-code"
                value={disableCode}
                onChange={(e) => setDisableCode(e.target.value)}
                placeholder="6-digit or recovery code"
                autoComplete="one-time-code"
              />
            </div>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                disabled={disableTotp.isPending || !disableCode.trim()}
                onClick={(e) => {
                  e.preventDefault();
                  void handleDisableTotp();
                }}
              >
                {disableTotp.isPending ? "Turning off…" : "Turn off"}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Regen recovery */}
        <AlertDialog
          open={regenOpen}
          onOpenChange={(open) => {
            setRegenOpen(open);
            if (!open) setNewRecoveryCodes(null);
          }}
        >
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>
                {newRecoveryCodes ? "Save your new recovery codes" : "Create new recovery codes"}
              </AlertDialogTitle>
              <AlertDialogDescription>
                {newRecoveryCodes
                  ? "Your old recovery codes no longer work. Copy or download these now."
                  : "This replaces your existing recovery codes. Enter a code from your authenticator app."}
              </AlertDialogDescription>
            </AlertDialogHeader>
            {newRecoveryCodes ? (
              <>
                <ul className="grid grid-cols-2 gap-2 rounded-md border border-border bg-muted/20 p-3 font-mono text-sm">
                  {newRecoveryCodes.map((item) => (
                    <li key={item}>{item}</li>
                  ))}
                </ul>
                <div className="flex flex-wrap gap-2">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      void navigator.clipboard.writeText(newRecoveryCodes.join("\n")).then(() => {
                        toast.success("Recovery codes copied");
                      });
                    }}
                  >
                    <Copy className="size-3.5" />
                    Copy all
                  </Button>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      const blob = new Blob([`${newRecoveryCodes.join("\n")}\n`], {
                        type: "text/plain",
                      });
                      const url = URL.createObjectURL(blob);
                      const a = document.createElement("a");
                      a.href = url;
                      a.download = "genesis-recovery-codes.txt";
                      a.click();
                      URL.revokeObjectURL(url);
                    }}
                  >
                    <Download className="size-3.5" />
                    Download
                  </Button>
                </div>
                <AlertDialogFooter>
                  <AlertDialogAction onClick={() => setRegenOpen(false)}>
                    <Check className="size-3.5" />
                    Done
                  </AlertDialogAction>
                </AlertDialogFooter>
              </>
            ) : (
              <>
                <div className="space-y-2 py-2">
                  <Label htmlFor="totp-regen-code">Authenticator code</Label>
                  <Input
                    id="totp-regen-code"
                    value={regenCode}
                    onChange={(e) => setRegenCode(e.target.value)}
                    placeholder="000000"
                    inputMode="numeric"
                    autoComplete="one-time-code"
                  />
                </div>
                <AlertDialogFooter>
                  <AlertDialogCancel>Cancel</AlertDialogCancel>
                  <AlertDialogAction
                    disabled={regenerateRecovery.isPending || !regenCode.trim()}
                    onClick={(e) => {
                      e.preventDefault();
                      void handleRegen();
                    }}
                  >
                    {regenerateRecovery.isPending ? "Creating…" : "Create codes"}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </>
            )}
          </AlertDialogContent>
        </AlertDialog>
      </div>

      {/* Devices */}
      <div className="space-y-3">
        <div>
          <h3 className="text-sm font-medium">Devices</h3>
          <p className="mt-1 text-xs text-muted-foreground">Devices signed into your account.</p>
        </div>

        {devicesLoading ? (
          <DevicesListSkeleton />
        ) : devicesError ? (
          <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-4 py-3 text-sm text-destructive">
            {devicesError}
          </div>
        ) : sessions.length === 0 ? (
          <SettingsEmptyState
            title="No active devices"
            description="When you sign in on a browser or app, it will show up here."
          />
        ) : (
          <div className={settingsCardClassName}>
            {sessions.map((session) => (
              <DeviceSessionRow
                key={session.id}
                session={session}
                revokingId={revokingId}
                onRevoke={handleRevoke}
              />
            ))}
          </div>
        )}
      </div>
    </SettingsSection>
  );
}

/**
 * WebAuthn / passkey host rules.
 *
 * Browsers require a domain-name RP ID. IP addresses (including 127.0.0.1) are
 * not valid. The only local HTTP exception is the hostname `localhost`.
 *
 * Genesis defaults to http://127.0.0.1:3500 for cookies; passkeys need
 * http://localhost:3500 (same process, different host string).
 *
 * Dev note: Vite proxies /api to 127.0.0.1:3501 with changeOrigin, so the
 * backend request URL host is often 127.0.0.1 even when the page is on
 * localhost. Always prefer Origin / X-Forwarded-Host for WebAuthn RP config.
 */

/** True when hostname is an IP literal (v4 / v6), not a domain name. */
export function isIpHostname(hostname: string): boolean {
  const host = hostname
    .trim()
    .toLowerCase()
    .replace(/^\[|\]$/g, "");
  if (!host) return false;
  // IPv4
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return true;
  // IPv6
  if (host.includes(":")) return true;
  return false;
}

/** Hostnames where WebAuthn may run over http (browser secure-context exception). */
export function isWebauthnLocalHttpHost(hostname: string): boolean {
  return hostname.trim().toLowerCase() === "localhost";
}

export type WebauthnHostSupport =
  | { supported: true }
  | {
      supported: false;
      /** Machine-readable reason. */
      reason: "ip_hostname" | "insecure_origin";
      /** User-facing explanation. */
      message: string;
      /** Suggested same-path URL on localhost when current host is loopback IP. */
      localhostUrl?: string;
    };

/**
 * Whether the current browser location can run WebAuthn ceremonies.
 * Call only in the browser (uses window.location).
 */
export function getBrowserWebauthnHostSupport(
  locationLike: Pick<
    Location,
    "protocol" | "hostname" | "port" | "pathname" | "search" | "hash"
  > = typeof window !== "undefined"
    ? window.location
    : ({
        protocol: "http:",
        hostname: "127.0.0.1",
        port: "3500",
        pathname: "/",
        search: "",
        hash: "",
      } as Location),
): WebauthnHostSupport {
  const { protocol, hostname } = locationLike;
  const isSecure = protocol === "https:" || isWebauthnLocalHttpHost(hostname);

  if (isIpHostname(hostname)) {
    const localhostUrl = buildLocalhostUrl(locationLike);
    return {
      supported: false,
      reason: "ip_hostname",
      message:
        "Passkeys can’t run on 127.0.0.1 (browsers require a domain name). Open Genesis at localhost, sign in again if needed, then set up your passkey.",
      localhostUrl,
    };
  }

  if (!isSecure) {
    return {
      supported: false,
      reason: "insecure_origin",
      message: "Passkeys require a secure connection (HTTPS) or localhost.",
    };
  }

  return { supported: true };
}

