/**
 * Consumer-facing labels for durable login sessions (Settings → Devices).
 * Keep strings plain — no schema/enum keys in UI.
 */

export function formatDeviceModality(modality: string | null | undefined): string {
  switch ((modality ?? "").trim().toLowerCase()) {
    case "web":
      return "Browser";
    case "desktop":
      return "Desktop app";
    case "mobile":
      return "Mobile app";
    case "mcp":
      return "MCP client";
    case "system":
      return "System";
    default:
      return "Unknown device";
  }
}

export function formatDeviceAuthMethod(method: string | null | undefined): string | null {
  const value = (method ?? "").trim().toLowerCase();
  if (!value) return null;
  switch (value) {
    case "login_code":
      return "Email code";
    case "google":
    case "genesis_google":
    case "catalyst_google":
      return "Google";
    case "passkey":
      return "Passkey";
    case "catalyst":
      return "Agent Company";
    case "desktop":
      return "Desktop";
    case "unknown":
      return null;
    default:
      return method?.trim() || null;
  }
}

/** Short browser/OS summary from a raw User-Agent string. */
export function summarizeUserAgent(userAgent: string | null | undefined): string {
  const ua = (userAgent ?? "").trim();
  if (!ua) return "Unknown browser";

  const isMobile = /Mobile|Android|iPhone|iPad/i.test(ua);
  let browser = "Browser";
  if (/Edg\//i.test(ua)) browser = "Edge";
  else if (/OPR\/|Opera/i.test(ua)) browser = "Opera";
  else if (/Chrome\//i.test(ua) && !/Edg\//i.test(ua)) browser = "Chrome";
  else if (/Firefox\//i.test(ua)) browser = "Firefox";
  else if (/Safari\//i.test(ua) && !/Chrome\//i.test(ua)) browser = "Safari";

  let os = "";
  if (/Windows/i.test(ua)) os = "Windows";
  else if (/Mac OS X|Macintosh/i.test(ua)) os = "macOS";
  else if (/Android/i.test(ua)) os = "Android";
  else if (/iPhone|iPad|iOS/i.test(ua)) os = "iOS";
  else if (/Linux/i.test(ua)) os = "Linux";

  if (os && isMobile) return `${browser} on ${os}`;
  if (os) return `${browser} on ${os}`;
  if (isMobile) return `${browser} (mobile)`;
  return browser;
}

export function formatDeviceLocationLabel(
  locationLabel: string | null | undefined,
  location?: {
    city?: string;
    region?: string;
    country?: string;
    raw?: string;
  } | null,
): string | null {
  const direct = locationLabel?.trim();
  if (direct) return direct;
  if (!location) return null;
  const parts = [location.city, location.region, location.country]
    .map((part) => part?.trim())
    .filter(Boolean);
  if (parts.length > 0) return parts.join(", ");
  const raw = location.raw?.trim();
  return raw || null;
}

