const queries = ["i18n", "localize", "internationalization"];
const results = await Promise.all(queries.map(async (query) => {
  const result = await tools.linear_list_issues({
    assignee: "me",
    query,
    limit: 100,
    orderBy: "updatedAt",
    includeArchived: true,
    fields: ["id", "title", "description", "status", "statusType", "labels", "project", "parentId", "url", "completedAt", "canceledAt", "updatedAt"]
  });
  return { query, result };
}));
const byId = new Map();
for (const { query, result } of results) {
  if (!result.ok) { emit({ query, error: result.error }); continue; }
  const issues = Array.isArray(result.data) ? result.data : (result.data?.issues ?? result.data?.nodes ?? []);
  for (const issue of issues) byId.set(issue.id, issue);
}
emit([...byId.values()]);
return { count: byId.size };

